using GeoCoordinate = std::pair<double, double>;

std::vector<map_model::Point> GeoRing(
    std::initializer_list<GeoCoordinate> coordinates) {
    std::vector<map_model::Point> ring;
    ring.reserve(coordinates.size());
    for (const GeoCoordinate coordinate : coordinates)
        ring.push_back(map_model::ProjectLonLat(coordinate.first,
                                                coordinate.second));
    return ring;
}

std::vector<map_model::Point> ConvexHull(
    std::vector<map_model::Point> points) {
    std::sort(points.begin(), points.end(), [](const auto& left, const auto& right) {
        return left.x < right.x ||
               (left.x == right.x && left.y < right.y);
    });
    points.erase(std::unique(points.begin(), points.end(), [](const auto& left,
                                                              const auto& right) {
        return std::abs(left.x - right.x) <= 0.0001f &&
               std::abs(left.y - right.y) <= 0.0001f;
    }), points.end());
    if (points.size() <= 2) return points;
    auto cross = [](const map_model::Point& a, const map_model::Point& b,
                    const map_model::Point& c) {
        return (b.x - a.x) * (c.y - a.y) -
               (b.y - a.y) * (c.x - a.x);
    };
    std::vector<map_model::Point> hull;
    hull.reserve(points.size() * 2);
    for (const auto& point : points) {
        while (hull.size() >= 2 &&
               cross(hull[hull.size() - 2], hull.back(), point) <= 0.0f)
            hull.pop_back();
        hull.push_back(point);
    }
    const std::size_t lowerSize = hull.size();
    for (std::size_t index = points.size(); index-- > 0;) {
        const auto& point = points[index];
        while (hull.size() > lowerSize &&
               cross(hull[hull.size() - 2], hull.back(), point) <= 0.0f)
            hull.pop_back();
        hull.push_back(point);
    }
    if (!hull.empty()) hull.pop_back();
    return hull;
}

void RebuildShapeMetadata(ProvinceShape& shape) {
    std::vector<map_model::Point> allPoints;
    for (const auto& part : shape.parts)
        allPoints.insert(allPoints.end(), part.begin(), part.end());
    if (allPoints.empty()) return;
    shape.vertices = ConvexHull(allPoints);
    shape.bounds = map_model::PolygonBounds(allPoints);
}

ProvinceShape* FindShape(std::vector<ProvinceShape>& shapes,
                         const char* stableKey) {
    for (ProvinceShape& shape : shapes)
        if (shape.stableKey == stableKey) return &shape;
    return nullptr;
}

